find results -type f -name '*.json' -exec python3 -c 'exec("import sys,json
for f in sys.argv[1:]:
    try:
        d=json.load(open(f))
    except Exception: continue
    if isinstance(d,dict) and d.get('status')=='failed': print(f)")' {} +

python3 -c 'import json,collections; d=json.load(open("tags.json", encoding="utf-8")); c=collections.Counter(); exec("def w(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if k=="tags" and isinstance(v,list): c.update(str(t) for t in v)
   else: w(v)
 elif isinstance(x,list):
  for y in x: w(y)
w(d)
for k,v in sorted(c.items()): print(f"{k}: {v}")")'
